import { createMemo, createSignal, flush, onCleanup } from "solid-js";

const [count] = createSignal(0);

export class Cleans {
  constructor() {
    onCleanup(() => {});
  }
}
export class Reads {
  constructor() {
    count();
  }
}
export class Takes {
  constructor(read) {
    read();
  }
}
export function makeCreates() {
  return {
    get value() {
      createMemo(() => 1);
      return 1;
    },
  };
}
export function makeFlushes() {
  return {
    get value() {
      flush();
      return 1;
    },
  };
}
export function flushes() {
  flush();
}
export function creates() {
  createMemo(() => 1);
}
export function reads() {
  return count();
}
export function tag(strings) {
  return count();
}
export function quiet() {
  return 1;
}
